#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  LOGFONT lf;  HFONT hFont;  HFONT hOld;  HFONT hStdF;  COLORREF color;  } Queue_FontC;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~typedef struct : public SPROLOZ  {  DWORD_PTR dwPlace;  } Queue_FontD;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~HFONT GetFont( char* font, COLORREF* color );void TegFont( LOGFONT& lf, STegScn* teg, COLORREF& color );//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Это на всякий случайvoid ClearFontC(SQueue& q,void* s)  {  Queue_FontC* p = (Queue_FontC*)s;  if ( p->hFont )    ::DeleteObject( p->hFont );  p->hFont = NULL;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintFontC(DefinePaint)  {  QueueP(Queue_FontC);  if ( p->color != 0xffffffff )  ::SetTextColor( hDC, p->color );  //  if ( p->hStdF != NULL )    {    p->hOld = (HFONT)::SelectObject(hDC,p->hStdF);    }  else    {    if ( p->hFont == NULL )    p->hFont = ::CreateFontIndirect( &p->lf );    p->hOld = (HFONT)::SelectObject(hDC,p->hFont);    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~int PaintFontD(DefinePaint)  {  QueueP(Queue_FontD);  if ( p->dwPlace != 0 )    {    DWORD dwReturn = GdiGetBatchLimit();    BOOL bReturn = GdiFlush();    HGDIOBJ* hGdi = (HGDIOBJ*)(beginQ+p->dwPlace);    ::SelectObject(hDC,hGdi[1]);    //if ( hGdi[0] )    //::DeleteObject( hGdi[0] );    //hGdi[0] = NULL;    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~DWORD_PTR dwFont[32];void AddFontC(DefineTegs)  {  static int nCount = sizeof(dwFont)/sizeof(dwFont[0])-1;  if ( def.fntCount > nCount )    return;  //  AddQueueEx(Queue_FontC);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintFontC;  p->clear = &ClearFontC;  //  TegFont( p->lf, teg, p->color );  //  if ( lstrlen( p->lf.lfFaceName ) == 1 )    sprintf_s( p->lf.lfFaceName, sizeof(p->lf.lfFaceName), "@%c", *p->lf.lfFaceName );  p->hStdF = ::GetFont( p->lf.lfFaceName, &p->color );  //  dwFont[def.fntCount] = (DWORD_PTR)(&p->hFont)-(DWORD_PTR)(Buffer.szQueue);  def.fntCount++;  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddFontD(DefineTegs)  {  if ( def.fntCount <= 0 )    return;  AddQueueEx(Queue_FontD);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintFontD;  //  def.fntCount--;  p->dwPlace = dwFont[def.fntCount];  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~